package com.github.kotlinz.kotlinz.data.tambara

import com.github.kotlinz.kotlinz.K1
import com.github.kotlinz.kotlinz.K2
import com.github.kotlinz.kotlinz.K3
import com.github.kotlinz.kotlinz.type.profunctor.Profunctor
import com.github.kotlinz.kotlinz.type.profunctor.Strong

/**
 * The Tambara module of a profunctor `P`: a value that works on `P<Pair<A, C>, Pair<B, C>>` for every
 * context type `C`. It is the free [Strong] profunctor generated by `P`.
 *
 * `P` is identified by the tags `PT, PF` (values `K3<PT, PF, _, _>`), bundled into the phantom [Of].
 *
 * Instances: [TambaraProfunctor], [TambaraStrong] (both need only `Profunctor<PT, PF>`).
 *
 * ```kotlin
 * val strong = object : Function1Strong {}
 * val t = Tambara.of(strong, Function1 { n: Int -> n + 1 })
 * Function1.narrow(t.run<String>())(Pair(1, "x"))  // (2, x)
 * Function1.narrow(t.untambara(strong))(1)         // 2
 * ```
 */
abstract class Tambara<PT, PF, A, B>: K3<Tambara.T, Tambara.Of<PT, PF>, A, B> {
  class T
  /** Phantom bundling the profunctor tags. */
  class Of<PT, PF>

  companion object {
    /** Downcasts a higher-kinded value back to [Tambara]. */
    fun <PT, PF, A, B> narrow(v: K1<K2<T, Of<PT, PF>, A>, B>): Tambara<PT, PF, A, B> = v as Tambara<PT, PF, A, B>

    /** Embeds a value of a [Strong] profunctor using its `first`. */
    fun <PT, PF, A, B> of(strong: Strong<PT, PF>, v: K3<PT, PF, A, B>): Tambara<PT, PF, A, B> = object: Tambara<PT, PF, A, B>() {
      override fun <C> run(): K3<PT, PF, Pair<A, C>, Pair<B, C>> = strong.first(v)
    }
  }

  /** Returns the underlying value acting on pairs with context type [C]. */
  abstract fun <C> run(): K3<PT, PF, Pair<A, C>, Pair<B, C>>

  /** Recovers a plain `P<A, B>` by choosing a trivial context. */
  fun untambara(profunctor: Profunctor<PT, PF>): K3<PT, PF, A, B> =
    profunctor.dimap({ a: A -> Pair(a, Unit) }, { p: Pair<B, Unit> -> p.first }, run<Unit>())
}
